package org.mockito.internal.stubbing.answers;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for CallsRealMethods.answer(InvocationOnMock invocation)
 */
public class CallsRealMethods_answer_TriageGen0Test {

    @Test
    public void testAnswerReturnsValueFromRealMethod() throws Throwable {
        // Arrange
        CallsRealMethods answerer = new CallsRealMethods();
        InvocationOnMock invocation = mock(InvocationOnMock.class);
        String expectedReturnValue = "realMethodResult";

        when(invocation.callRealMethod()).thenReturn(expectedReturnValue);

        // Act
        Object actualReturnValue = answerer.answer(invocation);

        // Assert
        assertEquals(expectedReturnValue, actualReturnValue);
    }

    @Test
    public void testAnswerReturnsNullFromRealMethod() throws Throwable {
        // Arrange
        CallsRealMethods answerer = new CallsRealMethods();
        InvocationOnMock invocation = mock(InvocationOnMock.class);

        when(invocation.callRealMethod()).thenReturn(null);

        // Act
        Object actualReturnValue = answerer.answer(invocation);

        // Assert
        assertNull(actualReturnValue);
    }

    @Test(expected = RuntimeException.class)
    public void testAnswerThrowsExceptionFromRealMethod() throws Throwable {
        // Arrange
        CallsRealMethods answerer = new CallsRealMethods();
        InvocationOnMock invocation = mock(InvocationOnMock.class);

        when(invocation.callRealMethod()).thenThrow(new RuntimeException("Exception from real method"));

        // Act
        answerer.answer(invocation);

        // Assert handled by expected exception
    }
}
